int scsi_emulate_command(SCSIDiskReq *r) {
    if (!r) {
        return -1;
    }

    if (r->command[0] == 0x1B) { /* Eject tray or check readiness */
        if (r->command[1] & 0x02) { /* Eject condition */
            if (r->device_type == 0x5) { /* ROM device type */
                if (r->tray_locked) {
                    return -1; /* Tray is locked, cannot eject */
                }
                r->tray_open = 1; /* Perform eject operation */
            } else {
                return -1; /* Eject not supported for this device type */
            }
        } else if (r->command[1] & 0x01) { /* Check readiness */
            if (!r->tray_open) {
                return -1; /* Unit not ready, tray is closed */
            }
        } else {
            return -1; /* Illegal request */
        }

        if (r->data_length > 0) {
            return -1; /* Illegal request: non-zero data transfer length */
        }

        return 0; /* Success */
    }

    return -1; /* Illegal request */
}
